mapper.select:
select o.*, m.name as goodsName, u.name as userName from orders o left join upcoming_movies m on o.goods_id = m.id left join user u on o.user_id = u.id
o.user_id = #{userId}
order by o.id desc

mapper.update:
update orders set order_no=#{orderNo}, goods_id=#{goodsId}, num=#{num}, user_id=#{userId}, 
status=#{status}, time=#{time}, total_price=#{totalPrice}, screening_id=#{screeningId}, 
seat_info=#{seatInfo}, hall_name=#{hallName}, show_time=#{showTime}
where id = #{id}
